mapper.select:
SELECT t.*, m.name as materialName, m.material_type as materialType, s.lot_number as lotNumber FROM inventory_transactions t JOIN inventory_stocks s ON t.stock_id = s.id JOIN materials m ON s.material_id = m.id
AND m.material_type = #{materialType}
AND t.transaction_type = #{transactionType}
ORDER BY t.transaction_date DESC
